//-------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
//	NAME:						HE_TimeSync
//	CREATOR:					Helgevold - William Veim
// REQUIREMENTS: 		NX CPU
//							
//-------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
// VERSION LOG:
//	VERSION			DATE				SIGN						DESCRIPTION
//	1.0.0					2024-09-09		William Veim        	Initial release
//	2.0.0					2025-03-25		William Veim        	Rework
//	2.0.1					2025-08-28		William Veim			Bug fixing
//	2.0.2					2025-08-28		Ruben Byman			Bug fixing time zones
//	
//================================================================================================================================
//
//			DESCRTIPTION: 	
//			Syncroniserer CPU klokke etter sommer/vintertid og NTP server. Tidssone må settes riktig i Controller Clock (GMT +01:00 Sweden)
//			NB! Blokken går i fault state dersom NTP sync intervall er over 12t, anbefaler 2t invervall på NTP settings		
//		
//===============================================================================================================================

//Rising edge for minute pulse
RE_MinutePulse(Clk:=Get1minClk());

//Sets UTC_Time to current CPU time
Local_Time := GetTime();

//FB for adjusting time according to summer/winter
FB_TimeChange(
  Enable:= TRUE
, UTCDateAndTime:=Local_Time 
, UTCZoneShift:=T#0h);

//Retrives data for summer/winter time
IF FB_TimeChange.DST_state THEN
	Wrk_SummerTime:=TRUE;
	Wrk_WinterTime:=FALSE;
	Wrk_WinterTimeAdjusted:=FALSE;
ELSE
	Wrk_WinterTime:=TRUE;
	Wrk_SummerTime:=FALSE;
	Wrk_SummerTimeAdjusted:=FALSE;
END_IF;

//Adjusting local time on change to summer time
IF Wrk_SummerTime AND NOT Wrk_SummerTimeAdjusted AND TimeZone_Active THEN
	Adjust_Time:=TRUE;
	New_Time:=  ADD_DT_TIME(In1:=Local_Time, In2:=T#1h);
	Wrk_SummerTimeAdjusted:=TRUE;
	
//Adjusting local time on change to winter time
ELSIF Wrk_WinterTime AND NOT Wrk_WinterTimeAdjusted AND TimeZone_Active THEN
	Adjust_Time:=TRUE;
	New_Time:=  SUB_DT_TIME(In1:=Local_Time, In2:=T#1h);
	Wrk_WinterTimeAdjusted:=TRUE;
	
//Set time sync accoring to NTP server time
ELSIF _EIP_NTPResult.ExecNormal AND NOT _EIP_NTPSrvErr AND (_EIP_NTPResult.ExecTime <> NTP_ExecTime_Sample) THEN
	
	IF Wrk_SummerTime THEN
		New_Time :=  ADD_DT_TIME(In1:=_EIP_NTPResult.ExecTime, In2:=T#1h);
	ELSIF Wrk_WinterTime THEN
		New_Time := _EIP_NTPResult.ExecTime;
	END_IF;
	
	Adjust_Time:=TRUE;
	NTP_ExecTime_Sample:=_EIP_NTPResult.ExecTime;
	
END_IF;

//Counting time since last sync
IF NOT Adjust_Time AND RE_MinutePulse.Q THEN
	TimeSince_Sync := TimeSince_Sync + 1;
ELSIF Adjust_Time THEN
	TimeSince_Sync := 0;
	FirstTime_Adjusted := TRUE;
END_IF;

//Adjusting time for CPU
IF Adjust_Time THEN
	SetTime(In:=New_Time);
	TimeSync_Exce:=New_Time;
	Adjust_Time:=FALSE;
END_IF;

//Fault state
IF P_First_Run OR P_First_RunMode THEN
	FirstTime_Adjusted := FALSE;
	NTP_ServerErr := FALSE;
ELSIF FirstTime_Adjusted THEN
	NTP_ServerErr := _EIP_NTPSrvErr;
END_IF;
TimeSync_Fault := NTP_ServerErr OR TimeSince_Sync >=  720;
